      es: ["Altura de la cascada: unos 50 m", "Superficie: aprox. 66 km² (toda la reserva de Yehudiya)", "Precipitación anual: aprox. 800 mm", "Punto más alto: aprox. 1.000 m sobre el nivel del mar", "Especies de árboles: roble de Tabor, pistacho atlántico, madroño", "Distancia al mar de Galilea: aprox. 15 km"],
      pt: ["Altura da cascata: cerca de 50 m", "Área: cerca de 66 km² (toda a Reserva de Yehudiya)", "Precipitação anual: cerca de 800 mm", "Elevação máxima: cerca de 1.000 m acima do nível do mar", "Espécies de árvores: carvalho-de-tabor, pistácio-atlântico, medronheiro", "Distância ao mar da Galileia: cerca de 15 km"],
