      pt: ["Caudal das nascentes: cerca de 130 milhões de m³ de água por ano", "Altura da cascata: cerca de 10 m", "Precipitação anual: mais de 1.000 mm", "Área: cerca de 10 km²", "Altitude: cerca de 350 m acima do nível do mar", "Cidade romana: Cesareia de Filipe, fundada no século I a.C."],
