    type: "national-park",
    parent: "IL-Z",
    coords: [35.61, 33.1],
    name: { de: "Hula-Naturschutzgebiet", hu: "Hula-völgy Nemzeti Park", ro: "Rezervația Hula", en: "Hula Nature Reserve"},
    image: "/poi-images/il-hula-valley-nature-v2.webp",
    description: {
      de: "Das Hula-Tal ist ein Feuchtgebiet von globaler Bedeutung, das Millionen von Zugvögeln auf ihrer Reise zwischen Europa und Afrika als Rastplatz dient.",
      hu: "A Hula-völgy egy globális jelentőségű vizenyős terület, amely vándormadarak millióinak szolgál pihenőhelyül az Európa és Afrika közötti útjukon.",
      ro: "Valea Hula este o zonă umedă de importanță globală, care servește drept loc de popas pentru milioane de păsări migratoare.",
      en: "The Hula Valley is a globally significant wetland that serves as a resting spot for millions of migratory birds traveling between Europe and Africa."
    },
    facts: {
      de: ["Paradies für Vogelbeobachter", "Bedeutende Feuchtgebiete", "Heimat seltener Tierarten", "Erfolgreich renaturiert"],
      hu: ["A madármegfigyelők paradicsoma", "Jelentős vizes élőhelyek", "Ritka állatfajok otthona", "Sikeresen helyreállított terület"],
      ro: ["Paradis pentru ornitologi", "Zone umede importante", "Găzduiește specii rare", "Zonă renaturată cu succes"],
      en: ["Birdwatcher's paradise", "Significant wetlands", "Home to rare animal species", "Successfully restored area"]
    }, image: "/poi-images/il-hula-valley-nature-v2.webp",
    descriptionAdvanced: {
      de: "Das Hula-Naturreservat im Norden Israels ist ein ökologisches Juwel und war 1964 das erste offizielle Naturschutzgebiet des Landes. Das Gebiet liegt im Hula-Tal, einem Teil des Syrisch-Afrikanischen Grabenbruchs, und war ursprünglich ein ausgedehnter See und Sumpfgebiet. In den 1950er Jahren wurde das Tal zur Gewinnung von Ackerland trockengelegt, was jedoch zu ökologischen Problemen führte, woraufhin ein Teil des Gebiets renaturiert wurde. Heute ist das Reservat einer der weltweit wichtigsten Rastplätze für Zugvögel auf ihrem Weg zwischen Europa, Asien und Afrika. Jährlich ziehen über 500 Millionen Vögel durch das Tal, darunter Zehntausende Kraniche, die hier oft überwintern. Besucher können über schwimmende Stege und durch Beobachtungsstationen die reiche Tierwelt erleben, zu der auch Wasserbüffel und seltene Sumpfpflanzen wie der Papyrus gehören. Das Reservat kombiniert aktiven Naturschutz mit modernster wissenschaftlicher Forschung zur Vogelzugforschung. Die Wiedervernässung eines Teils des Tals in den 1990er Jahren hat die Artenvielfalt massiv erhöht und den Tourismus in der Region nachhaltig gefördert.",
      hu: "A Hula-természetvédelmi terület Izrael északi részén egy ökológiai ékszerdoboz, amely 1964-ben az ország első hivatalos védett területe lett. A Hula-völgyben található, amely a Szír-Afrikai árokrendszer része, és eredetileg egy kiterjedt tó és mocsárvidék volt. Az 1950-es években a völgyet lecsapolták mezőgazdasági területek nyerése érdekében, ami azonban ökológiai problémákhoz vezetett, ezért később a terület egy részét rehabilitálták. Ma a rezervátum a világ egyik legfontosabb pihenőhelye a vándorló madarak számára Európa, Ázsia és Afrika közötti útjukon. Évente több mint 500 millió madár vonul át a völgyön, köztük több tízezer daru, amelyek gyakran itt is telelnek. A látogatók úszó pallókon és megfigyelőállomásokon keresztül ismerhetik meg a gazdag állatvilágot, amelyhez vízibivalyok és ritka mocsári növények, például papirusz is tartozik. A rezervátum ötvözi az aktív természetvédelmet a madárvonulás modern tudományos kutatásával. A völgy egy részének 1990-es évekbeli újraárasztása jelentősen növelte a biodiverzitást és fellendítette a régió fenntartható turizmusát.",
      ro: "Rezervația Naturală Hula din nordul Israelului este o bijuterie ecologică și a fost prima arie protejată oficială a țării, înființată în 1964. Zona este situată în Valea Hula, parte a sistemului de falii Siriaco-African, și a fost inițial un lac întins și o zonă mlăștinoasă. În anii 1950, valea a fost drenată pentru a obține teren agricol, fapt ce a dus la probleme ecologice, determinând ulterior renaturarea unei părți a zonei. Astăzi, rezervația este unul dintre cele mai importante puncte de oprire din lume pentru păsările migratoare în drumul lor între Europa, Asia și Africa. Anual, peste 500 de milioane de păsări tranzitează valea, inclusiv zeci de mii de cocori care aleg adesea să ierneze aici. Vizitatorii pot explora viața sălbatică bogată prin intermediul pontoanelor plutitoare și al stațiilor de observație, putând vedea bivoli de apă și plante rare de mlaștină, cum este papirusul. Rezervația combină conservarea activă cu cercetarea științifică modernă privind migrația păsărilor. Realimentarea cu apă a unei părți din vale în anii 1990 a crescut masiv biodiversitatea și a stimulat turismul sustenabil în întreaga regiune.",
      en: "The Hula Nature Reserve in northern Israel is an ecological jewel and was the country's first official nature reserve, established in 1964. Located in the Hula Valley, part of the Great Rift Valley, the area was originally a vast lake and swampland. In the 1950s, the valley was drained to create agricultural land, which led to significant ecological issues, prompting the eventual restoration of a portion of the wetlands. Today, the reserve is one of the world's most important stopover points for migratory birds on their journey between Europe, Asia, and Africa. Over 500 million birds pass through the valley annually, including tens of thousands of cranes that often overwinter here. Visitors can experience the rich wildlife via floating bridges and observation points, observing water buffalo and rare marsh plants such as papyrus. The reserve integrates active conservation with cutting-edge scientific research on avian migration patterns. The re-flooding of part of the valley in the 1990s has dramatically increased biodiversity and successfully boosted sustainable tourism in the region.",
    },
    factsAdvanced: {
      de: ["Das Reservat wurde 1964 als Israels erstes Naturschutzgebiet eröffnet.", "Über 500 Millionen Zugvögel passieren das Hula-Tal jedes Jahr.", "Zehntausende Kraniche nutzen das Reservat als Winterquartier.", "Im Reservat wächst der nördlichste wilde Papyrus der Welt.", "Eine Herde Wasserbüffel (Jamuss) pflegt die Sumpfvegetation.", "In den 1950er Jahren wurden 60.000 Dunam Sumpfland trockengelegt."],
      hu: ["A rezervátum 1964-ben nyílt meg Izrael első természetvédelmi területeként.", "Évente több mint 500 millió vándormadár halad át a Hula-völgyön.", "Darvak tízezrei használják a rezervátumot téli szálláshelyként.", "Itt található a világ legészakibb vadon élő papirusz-állománya.", "Egy bivalycsorda (Jamuss) segít fenntartani a mocsári vegetációt.", "Az 1950-es években 60 000 dunam mocsarat csapoltak le a völgyben."],
      ro: ["Rezervația a fost deschisă în 1964 ca prima arie protejată din Israel.", "Peste 500 de milioane de păsări migratoare trec prin Valea Hula anual.", "Zeci de mii de cocori folosesc rezervația ca loc de iernare.", "Aici crește cel mai nordic papirus sălbatic din întreaga lume.", "O turmă de bivoli de apă ajută la întreținerea vegetației de mlaștină.", "În anii 1950, au fost drenați 60.000 de dunami de mlaștină."],
      en: ["The reserve opened in 1964 as Israel's very first nature reserve.", "Over 500 million migratory birds pass through the Hula Valley each year.", "Tens of thousands of cranes use the reserve as their wintering grounds.", "It is home to the northernmost wild papyrus growth in the world.", "A herd of water buffalo helps maintain the balance of marsh vegetation.", "60,000 dunams of swampland were drained in the valley during the 1950s."],
    },
