    facts: {
      de: ["Vulkanischer Kratersee", "Liegt in den Golanhöhen", "Von Apfelplantagen umgeben", "Kein natürlicher Abfluss"],
      hu: ["Vulkáni krátertó", "A Golán-fennsíkon fekszik", "Almaültetvények veszik körül", "Nincs természetes lefolyása"],
      ro: ["Lac de crater vulcanic", "Situat în Înălțimile Golan", "Înconjurat de livezi de meri", "Fără scurgere naturală"],
      en: ["Volcanic crater lake", "Located in the Golan Heights", "Surrounded by apple orchards", "No natural outlet"]
    }, image: "/poi-images/il-lake-ram-nature-v2.webp",
    descriptionAdvanced: {
      de: "Der Lake Ram, auch bekannt als Birket Ram, ist ein markanter Kratersee im nordöstlichen Teil der Golanhöhen nahe der Ortschaft Mas'ade. Geologisch handelt es sich um ein Maar, das durch eine phreatomagmatische Explosion entstand, als aufsteigendes Magma auf Grundwasser traf. Der See liegt auf einer Höhe von etwa 940 Metern über dem Meeresspiegel und hat einen Durchmesser von rund 800 Metern. Er besitzt keinen oberirdischen Abfluss und wird hauptsächlich durch Niederschläge sowie unterirdische Quellen gespeist, was zu einer maximalen Tiefe von etwa 10 Litern führt. Die Umgebung ist von Obstplantagen geprägt, insbesondere Äpfeln und Kirschen, die von der lokalen drusischen Bevölkerung bewirtschaftet werden. In der Archäologie erlangte der Ort weltweite Bekanntheit durch den Fund der 'Venus vom See Ram', einer etwa 230.000 bis 800.000 Jahre alten Steinfigur, die als eines der ältesten Beispiele für menschliche Symbolkunst gilt. Heute dient der See als wichtiges Wasserreservoir für die Landwirtschaft und als markantes Landschaftselement am Fuße des Berges Hermon.",
      hu: "A Ram-tó, arabul Birket Ram, egy különleges kráter-tó a Golan-fennsík északkeleti részén, Maszade falu közelében. Geológiailag egy maar, amely egy hatalmas gőzrobbanás következtében jött létre, amikor a feltörő magma talajvízzel érintkezett. A tó felszíne 940 méterrel található a tengerszint felett, átmérője pedig nagyjából 800 méter, ami szinte tökéletes kör alakot kölcsönöz neki. Mivel nincs természetes felszíni kifolyása, vizét főként a csapadék és a föld alatti források biztosítják, mélysége pedig eléri a 10 métert. A tó körüli területet a helyi drúz közösség által gondozott alma- és cseresznyéskertek övezik, amelyek a vulkanikus talajnak köszönhetően rendkívül termékenyek. Régészeti szempontból kiemelkedő a 'Ram-tavi Vénusz' néven ismert lelet, egy több százezer éves kőszobrocska, amely az emberi művészet egyik legkorábbi bizonyítéka lehet. A tó napjainkban fontos tározóként szolgál a mezőgazdaság számára, és az egyik leglátványosabb természeti képződmény a Hermon-hegy lábánál.",
      ro: "Lacul Ram, cunoscut și sub numele de Birket Ram, este un lac de crater situat în partea de nord-est a Podișului Golan, lângă localitatea Mas'ade. Din punct de vedere geologic, acesta este un maar, format în urma unei explozii freatomagmatice violente declanșate de interacțiunea magmei cu apele subterane. Lacul se află la o altitudine de aproximativ 940 de metri deasupra nivelului mării și are un diametru de circa 800 de metri, formând un cerc aproape perfect. Nu are nicio scurgere naturală la suprafață, fiind alimentat exclusiv de precipitații și izvoare subterane, atingând o adâncime de până la 10 metri. Malurile sale sunt înconjurate de livezi de meri și cireși, cultivate de comunitatea druză locală pe solul vulcanic fertil. Situl este celebru în arheologie pentru descoperirea „Venerei din Berekhat Ram”, o figurină de piatră datată între 230.000 și 800.000 de ani, considerată una dintre cele mai vechi forme de artă simbolică. Astăzi, lacul funcționează ca un rezervor strategic de apă pentru irigații și este o destinație peisagistică majoră.",
      en: "Lake Ram, also referred to as Birket Ram, is a prominent crater lake located in the northeastern Golan Heights near the Druze village of Mas'ade. Geologically, it is classified as a maar, created by a powerful phreatomagmatic explosion that occurred when rising magma encountered groundwater. Situated at an elevation of 940 meters above sea level, the lake spans approximately 800 meters in diameter and maintains a nearly circular shape. It lacks any surface outlets, relying instead on direct rainfall and subterranean springs to maintain its depth, which reaches up to 10 meters. The surrounding landscape is dominated by fertile volcanic soil, utilized by the local Druze population for extensive apple and cherry orchards. The lake gained international archaeological fame following the discovery of the 'Venus of Berekhat Ram,' a stone figurine estimated to be between 230,000 and 800,000 years old, representing one of the earliest examples of symbolic art. Currently, the lake serves as a vital irrigation reservoir and a scenic landmark at the southern foot of Mount Hermon.",
    },
    factsAdvanced: {
      de: ["Der See liegt auf einer Höhe von 940 Metern über dem Meeresspiegel.", "Der Durchmesser des fast kreisförmigen Sees beträgt etwa 800 Meter.", "Geologisch ist der See ein Maar und kein klassischer Vulkankrater.", "Die Venus vom See Ram wurde 1981 in der Nähe des Ufers entdeckt.", "Das Alter der dortigen Venus-Figur wird auf mindestens 230.000 Jahre geschätzt.", "Der See dient als wichtiges Wasserreservoir für die lokalen Obstplantagen."],
      hu: ["A tó felszíne 940 méteres tengerszint feletti magasságban található.", "A víztükör átmérője körülbelül 800 méter, alakja majdnem kerek.", "A tó kialakulása egy gőzrobbanásos vulkáni eseménynek köszönhető.", "A híres Ram-tavi Vénusz szobrocskát 1981-ben találták meg itt.", "A lelet kora 230 és 800 ezer év közé tehető a rétegtani adatok alapján.", "A tó vizét a környező drúz falvak használják öntözésre."],
      ro: ["Lacul Ram este situat la o altitudine de 940 m în nordul Golanului.", "Diametrul lacului este de aproximativ 800 de metri.", "Este format într-un maar, rezultat dintr-o explozie freatomagmatică.", "Figurina „Venera din Ram” a fost descoperită aici în anul 1981.", "Această figurină este sculptată în tuf vulcanic roșu (scorie).", "Adâncimea maximă a apei în centrul lacului este de circa 10 metri."],
      en: ["The lake is situated at an elevation of 940 meters above sea level.", "It measures approximately 800 meters across in a circular basin.", "Geologists identify the formation as a maar rather than a caldera.", "The Venus of Berekhat Ram was discovered here in 1981.", "The stone figurine is considered one of the world's oldest art pieces.", "The lake is a primary source of irrigation for local cherry orchards."],
    },
