      en: "The Alexander River flows into the Mediterranean coast and is especially known for its population of African softshell turtles.",
      es: "El río Alexander fluye hacia la costa mediterránea y es especialmente conocido por su población de tortugas de caparazón blando africanas.",
      pt: "O rio Alexander corre para a costa mediterrânica e é particularmente conhecido pela sua população de tartarugas-de-carapaça-mole-africanas.",
      fr: "La rivière Alexander se jette dans la côte méditerranéenne et est particulièrement connue pour sa population de tortues à carapace souple d'Afrique.",
