      ro: ["Casa broaștelor țestoase cu carapace moale", "Se varsă în Marea Mediterană", "Râu curățat cu succes", "Parcuri riverane frumoase"],
      en: ["Home to softshell turtles", "Empties into the Mediterranean Sea", "Successfully cleaned river", "Beautiful riverside parks"],
      es: ["Hogar de tortugas de caparazón blando", "Desemboca en el Mediterráneo", "Limpiado con éxito", "Hermosos parques ribereños"],
      pt: ["Lar de tartarugas-de-carapaça-mole", "Desagua no Mediterrâneo", "Limpo com sucesso", "Belos parques ribeirinhos"],
      fr: ["Habitat des tortues à carapace souple", "Se jette dans la Méditerranée", "Nettoyé avec succès", "Beaux parcs sur les berges"],
