      ro: ["Lungimea râului Alexander este de aproximativ 45 km.", "Țestoasele de aici sunt cele mai mari reptile de apă dulce din regiune.", "Restaurarea râului a fost un efort comun între autoritățile israeliene și palestiniene.", "Podul Țestoaselor a fost construit special pentru observații turistice.", "Vărsarea râului în mare formează un estuar cu biodiversitate ridicată.", "Traseul de drumeție de-a lungul râului are o lungime de circa 7 km."],
      en: ["The Alexander River spans 45 kilometers from source to sea.", "It is home to the African softshell turtle, which can weigh up to 50 kg.", "The restoration project won the International Riverprize in Australia in 2003.", "The river's mouth at Beit Yanai is part of a protected national park.", "Rehabilitation involved planting thousands of native aquatic plants.", "The Turtle Bridge attracts over 200,000 visitors annually."],
      es: ["El río Alexander tiene una longitud total de unos 45 kilómetros.", "La tortuga de caparazón blando africana puede llegar a pesar más de 50 kg aquí.", "El proyecto de saneamiento ganó el premio internacional Thiess River Prize en 2003.", "El río desemboca en la playa de Beit Yanai en el mar Mediterráneo.", "En el Puente de las Tortugas hay plataformas de observación especiales.", "Las tortugas ponen sus huevos en los bancos de arena a lo largo de las orillas."],
      pt: ["O rio Alexander tem um comprimento total de cerca de 45 quilómetros.", "A tartaruga-de-carapaça-mole-africana pode pesar aqui mais de 50 kg.", "O projeto de saneamento ganhou o prémio internacional Thiess River Prize em 2003.", "O rio desagua na praia de Beit Yanai no Mar Mediterrâneo.", "Na Ponte das Tartarugas existem plataformas de observação especiais.", "As tartarugas põem os seus ovos nos bancos de areia ao longo das margens."],
      fr: ["La rivière Alexander a une longueur totale d'environ 45 kilomètres.", "La tortue à carapace souple d'Afrique peut peser ici plus de 50 kg.", "Le projet d'assainissement a remporté le prix international Thiess River Prize en 2003.", "La rivière se jette dans la mer Méditerranée sur la plage de Beit Yanai.", "Des plateformes d'observation spéciales se trouvent au Pont des Tortues.", "Les tortues pondent leurs œufs dans les bancs de sable le long des berges."],
